/* Shelf: a minimal launcher for Samsung Tizen TVs.
 * Data comes from apps.js (generated by scripts/prepare-launcher.py).
 * Runs in a desktop browser too (preview mode): arrows + Enter, launches are simulated. */
(function () {
    "use strict";

    var data = window.SHELF_DATA;

    // Scale the 1920x1080 stage to whatever viewport the TV gives the app.
    var stage = document.getElementById("stage");
    function fit() {
        var s = Math.min(window.innerWidth / 1920, window.innerHeight / 1080);
        stage.style.transform = "scale(" + s + ")";
    }
    fit();
    window.addEventListener("resize", fit);
    var onTv = typeof window.tizen !== "undefined";
    var KEY = { LEFT: 37, UP: 38, RIGHT: 39, DOWN: 40, ENTER: 13, RETURN: 10009, BACKSPACE: 8 };
    var WALL_MS = 45000;

    var rows = [data.dock, data.apps];
    var rowEls = [document.getElementById("dock"), document.getElementById("more")];
    var pos = { row: 0, col: 0 };
    var memory = [0, 0]; // last column per row, so up/down returns where you were

    function tileFor(app) {
        var t = document.createElement("div");
        t.className = "tile";
        t.style.background = app.bg;
        if (app.icon) {
            var img = document.createElement("img");
            img.src = app.icon;
            img.alt = app.title;
            t.appendChild(img);
        } else {
            var l = document.createElement("span");
            l.className = "label";
            l.textContent = app.title;
            t.appendChild(l);
        }
        return t;
    }

    rows.forEach(function (list, r) {
        list.forEach(function (app) { rowEls[r].appendChild(tileFor(app)); });
    });

    var title = document.getElementById("shelfTitle");
    var hint = document.getElementById("shelfHint");
    var rowsWrap = document.querySelector(".rows");

    function render() {
        var prev = document.querySelector(".tile.focus");
        if (prev) prev.classList.remove("focus");
        var el = rowEls[pos.row].children[pos.col];
        el.classList.add("focus");
        rowsWrap.classList.toggle("low", pos.row === 1);

        // Scroll a row sideways so the focused tile stays on screen.
        var tileW = el.offsetWidth + 40;
        var visible = Math.floor((1920 - 96 - 96) / tileW);
        var shift = Math.max(0, pos.col - visible + 1) * tileW;
        rowEls[pos.row].style.transform = "translateX(" + -shift + "px)";

        var app = rows[pos.row][pos.col];
        title.textContent = app.title;
        hint.textContent = "Press OK to open";
    }

    function move(dr, dc) {
        if (dr) {
            var nr = pos.row + dr;
            if (nr < 0 || nr >= rows.length || !rows[nr].length) return;
            memory[pos.row] = pos.col;
            pos.row = nr;
            pos.col = Math.min(memory[nr], rows[nr].length - 1);
        } else {
            var nc = pos.col + dc;
            if (nc < 0 || nc >= rows[pos.row].length) return;
            pos.col = nc;
        }
        render();
    }

    var toastEl = document.getElementById("toast");
    var toastTimer;
    function toast(msg) {
        toastEl.textContent = msg;
        toastEl.classList.add("on");
        clearTimeout(toastTimer);
        toastTimer = setTimeout(function () { toastEl.classList.remove("on"); }, 2500);
    }

    function launch() {
        var app = rows[pos.row][pos.col];
        if (!onTv) { toast("Preview: would open " + app.title); return; }
        try {
            tizen.application.launch(app.tizenId, null, function (e) {
                toast("Couldn't open " + app.title + " (" + e.name + ")");
            });
        } catch (e) {
            toast("Couldn't open " + app.title);
        }
    }

    function exit() {
        if (onTv) tizen.application.getCurrentApplication().exit();
    }

    document.addEventListener("keydown", function (e) {
        switch (e.keyCode) {
            case KEY.LEFT: move(0, -1); break;
            case KEY.RIGHT: move(0, 1); break;
            case KEY.UP: move(-1, 0); break;
            case KEY.DOWN: move(1, 0); break;
            case KEY.ENTER: launch(); break;
            case KEY.RETURN:
            case KEY.BACKSPACE: exit(); break;
            default: return;
        }
        e.preventDefault();
    });

    // Wallpapers: two layers cross-fade. The timer runs only while the app is visible.
    var walls = [document.getElementById("wallA"), document.getElementById("wallB")];
    var place = document.getElementById("place");
    var wi = Math.floor(Math.random() * data.wallpapers.length);
    var front = 0;
    var wallTimer = null;

    function showWall() {
        var w = data.wallpapers[wi];
        var next = walls[1 - front];
        var img = new Image();
        img.onload = function () {
            next.style.backgroundImage = "url('" + w.src + "')";
            next.classList.add("on");
            walls[front].classList.remove("on");
            front = 1 - front;
            place.textContent = w.label;
        };
        img.src = w.src;
        wi = (wi + 1) % data.wallpapers.length;
    }

    function startWalls() {
        if (!wallTimer) wallTimer = setInterval(showWall, WALL_MS);
    }
    function stopWalls() {
        clearInterval(wallTimer);
        wallTimer = null;
    }

    document.addEventListener("visibilitychange", function () {
        if (document.hidden) stopWalls(); else { showWall(); startWalls(); }
    });

    var clock = document.getElementById("clock");
    function tick() {
        var d = new Date();
        var h = d.getHours(), m = d.getMinutes();
        clock.textContent = ((h + 11) % 12 + 1) + ":" + (m < 10 ? "0" : "") + m + (h < 12 ? " AM" : " PM");
    }

    // Preview only: ?row=1&col=3 sets the starting focus, for screenshots.
    if (!onTv) {
        var q = /row=(\d+).*col=(\d+)/.exec(location.search);
        if (q) { pos.row = Math.min(+q[1], 1); pos.col = Math.min(+q[2], rows[pos.row].length - 1); }
    }

    tick();
    setInterval(tick, 10000);
    showWall();
    startWalls();
    render();
})();
